CREATE TABLE food_batches (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), food_name VARCHAR(160) NOT NULL, food_category VARCHAR(60) NOT NULL, quantity NUMERIC(18,3) NOT NULL CHECK(quantity >= 0), unit VARCHAR(30) NOT NULL, expiry_date DATE, storage_location VARCHAR(180), status VARCHAR(24) NOT NULL DEFAULT 'AVAILABLE', recorded_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_food_batches_community_expiry ON food_batches(community_id,expiry_date);
CREATE TABLE water_sources (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), name VARCHAR(160) NOT NULL, source_type VARCHAR(40) NOT NULL, estimated_liters NUMERIC(18,3) CHECK(estimated_liters IS NULL OR estimated_liters >= 0), potable_status VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN', latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE', recorded_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE INDEX idx_water_sources_community ON water_sources(community_id,status);
CREATE TABLE water_quality_tests (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), source_id UUID NOT NULL REFERENCES water_sources(id), tested_by UUID REFERENCES app_users(id), ph_value NUMERIC(4,2) CHECK(ph_value IS NULL OR ph_value BETWEEN 0 AND 14), turbidity_ntu NUMERIC(10,3) CHECK(turbidity_ntu IS NULL OR turbidity_ntu >= 0), ecoli_detected BOOLEAN, screening_result VARCHAR(30) NOT NULL, notes TEXT, tested_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_water_tests_source_time ON water_quality_tests(source_id,tested_at DESC);
CREATE TABLE energy_assets (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), name VARCHAR(160) NOT NULL, asset_type VARCHAR(40) NOT NULL, capacity_kwh NUMERIC(18,3) CHECK(capacity_kwh IS NULL OR capacity_kwh >= 0), current_output_kw NUMERIC(18,3) CHECK(current_output_kw IS NULL OR current_output_kw >= 0), operational_status VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN', location_description VARCHAR(180), last_service_at TIMESTAMPTZ, recorded_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_energy_assets_community ON energy_assets(community_id,operational_status);
